CREATE SCHEMA extensions;
CREATE TABLE ca_launch_accounting_boundaries(scope_kind text,scope_id uuid,cutoff_at timestamptz,undone_at timestamptz,PRIMARY KEY(scope_kind,scope_id));
CREATE TABLE accounting_cash_rake_sources(id uuid,rake_record_id uuid,player_id uuid,club_id uuid,union_id uuid,coordinator_union_id uuid,earned_at timestamptz,rake_credit numeric,contract jsonb);
CREATE INDEX cash_standalone ON accounting_cash_rake_sources(coordinator_union_id,earned_at,club_id);
CREATE TABLE accounting_tournament_fee_sources(id uuid,rake_record_id uuid,tournament_id uuid,player_id uuid,club_id uuid,union_id uuid,coordinator_union_id uuid,charged_at timestamptz,rake_credit numeric,contract jsonb);
CREATE TABLE accounting_tournament_recognized_sources(source_id uuid,tournament_id uuid,recognized_at timestamptz,disposition text,rake_credit numeric);
CREATE TABLE accounting_tournament_fee_recognitions(tournament_id uuid,recognized_at timestamptz,status text,union_id uuid);
CREATE TABLE unions(id uuid PRIMARY KEY);
CREATE TABLE clubs(id uuid PRIMARY KEY,is_union boolean);
CREATE TABLE union_settlement_floor(union_id uuid PRIMARY KEY,earliest_period_start timestamptz);
CREATE TABLE club_settlement_floor(club_id uuid PRIMARY KEY,earliest_period_start timestamptz);
CREATE TABLE union_clubs(club_id uuid,union_id uuid);
CREATE TABLE agents(club_id uuid,is_prepaid boolean,credit_used numeric);
CREATE TABLE rakeback_periods(club_id uuid,period_start date,period_end date,status text);
CREATE TABLE union_accounting_runs(union_id uuid,standalone_club_id uuid,period_start timestamptz,period_end timestamptz,status text,result jsonb,scope_kind text,scope_id uuid,last_scheduler_visit_at timestamptz,started_at timestamptz);
CREATE TABLE weekly_accounting_scheduler_visits(scope_kind text,scope_id uuid,last_visit_at timestamptz,last_outcome text);
INSERT INTO clubs SELECT md5('club'||g)::uuid,false FROM generate_series(1,5)g;
INSERT INTO unions SELECT md5('union'||g)::uuid FROM generate_series(1,3)g;
INSERT INTO union_clubs VALUES(md5('club5')::uuid,md5('union1')::uuid);
INSERT INTO club_settlement_floor SELECT id,'2026-09-21 07:00Z' FROM clubs;
UPDATE club_settlement_floor SET earliest_period_start='2026-09-23 10:00Z' WHERE club_id=md5('club2')::uuid;
INSERT INTO union_settlement_floor SELECT id,'2026-09-21 07:00Z' FROM unions;
UPDATE union_settlement_floor SET earliest_period_start='2026-09-24 12:00Z' WHERE union_id=md5('union2')::uuid;
INSERT INTO accounting_cash_rake_sources SELECT md5('cash'||g)::uuid,md5('rake'||g)::uuid,md5('player'||g)::uuid,CASE WHEN g%23=0 THEN NULL ELSE md5('club'||(1+g%4))::uuid END,NULL,CASE WHEN g%19=0 THEN md5('union1')::uuid ELSE NULL END,CASE WHEN g%29=0 THEN NULL ELSE '2026-09-21 06:59Z'::timestamptz+(g%650)*interval '1 hour' END,1,'{}' FROM generate_series(1,2400)g;
INSERT INTO accounting_cash_rake_sources VALUES(md5('exact-end')::uuid,NULL,NULL,md5('club1')::uuid,NULL,NULL,'2026-10-12 07:00Z',1,'{}'),(md5('future')::uuid,NULL,NULL,md5('club1')::uuid,NULL,NULL,'2026-10-13 07:00Z',1,'{}');
INSERT INTO accounting_tournament_fee_sources SELECT md5('fee'||g)::uuid,NULL,md5('t'||g)::uuid,NULL,md5('club'||(1+g%4))::uuid,NULL,NULL,'2026-09-25 07:00Z',2,'{}' FROM generate_series(1,8)g;
INSERT INTO accounting_tournament_recognized_sources SELECT id,tournament_id,'2026-10-06 07:00Z',CASE WHEN id=md5('fee2')::uuid THEN 'cancelled' ELSE 'earned' END,CASE WHEN id=md5('fee3')::uuid THEN 3 ELSE 2 END FROM accounting_tournament_fee_sources;
INSERT INTO accounting_tournament_fee_recognitions SELECT tournament_id,'2026-10-06 07:00Z',CASE WHEN id=md5('fee4')::uuid THEN 'pending' ELSE 'recognized' END,NULL FROM accounting_tournament_fee_sources;
INSERT INTO accounting_tournament_recognized_sources SELECT * FROM accounting_tournament_recognized_sources WHERE source_id=md5('fee1')::uuid;
INSERT INTO rakeback_periods VALUES(md5('club3')::uuid,'2026-09-14','2026-09-20','pending');
INSERT INTO agents VALUES(md5('club4')::uuid,false,12),(md5('club2')::uuid,true,14);
INSERT INTO union_accounting_runs VALUES(md5('union1')::uuid,NULL,'2026-09-21 07:00Z','2026-09-28 07:00Z','failed','{}','union',md5('union1')::uuid,'2026-10-13 13:44Z','2026-10-13 13:40Z'),(NULL,md5('club4')::uuid,'2026-09-28 07:00Z','2026-10-05 07:00Z','complete','{"success":true,"accounting_version":3}','club',md5('club4')::uuid,NULL,'2026-10-10 07:00Z');
INSERT INTO weekly_accounting_scheduler_visits VALUES('union',md5('union1')::uuid,'2026-10-13 13:44Z','statement_timeout'),('club',md5('club1')::uuid,'2026-10-13 12:00Z','visited');
INSERT INTO accounting_cash_rake_sources(id,club_id,earned_at) VALUES(md5('cut-before')::uuid,md5('club1')::uuid,'2026-10-01 06:59:59Z'),(md5('cut-equal')::uuid,md5('club1')::uuid,'2026-10-01 07:00:00Z'),(md5('cut-after')::uuid,md5('club1')::uuid,'2026-10-01 07:00:01Z'),(md5('cut-equal-duplicate')::uuid,md5('club1')::uuid,'2026-10-01 07:00:00Z'),(md5('positive-infinity')::uuid,md5('club1')::uuid,'infinity'),(md5('explicit-null')::uuid,md5('club1')::uuid,NULL);
ANALYZE;
